// =============================================================
// 🎯 FILTER, SCORE & DEDUPE - Sélection pour audience IA technique
// =============================================================
// Filtre par pertinence LLM/IA, score, déduplique.
// Fallback vers contenu éducatif si pas de news pertinente.
// =============================================================

const articles = items.map(item => item.json);
const context = $('📅 Set Context & Dates').first().json;

// === MOTS-CLÉS TECHNIQUES HIGH VALUE (+3 pts) ===
const highValueKeywords = [
  // Entreprises & Modèles majeurs
  'openai', 'gpt-4', 'gpt-5', 'gpt-4o', 'gpt-4-turbo', 'chatgpt', 'o1', 'o3', 'o1-preview',
  'anthropic', 'claude', 'claude 3', 'claude 3.5', 'claude 4', 'sonnet', 'opus', 'haiku',
  'google', 'gemini', 'gemini 2', 'gemini ultra', 'gemini pro', 'gemini flash', 'deepmind', 'bard',
  'meta', 'llama', 'llama 3', 'llama 3.1', 'llama 4', 'code llama',
  'xai', 'grok', 'grok 2', 'grok 3', 'elon musk',
  'deepseek', 'deepseek v3', 'deepseek coder', 'deepseek-r1',
  'mistral', 'mixtral', 'mistral large', 'mistral medium',
  'microsoft', 'copilot', 'phi-3', 'phi-4', 'azure openai',
  'perplexity', 'cohere', 'command r', 'command r+',
  'nvidia', 'blackwell', 'h100', 'h200', 'gb200',

  // Concepts techniques LLM
  'llm', 'large language model', 'transformer', 'attention',
  'rag', 'retrieval augmented generation', 'retrieval-augmented',
  'fine-tuning', 'fine tuning', 'finetuning', 'lora', 'qlora',
  'prompt engineering', 'chain of thought', 'cot', 'reasoning',
  'multimodal', 'vision language', 'vlm', 'text-to-image',
  'embedding', 'vector database', 'vectorstore', 'pinecone', 'weaviate', 'chroma',
  'agent', 'agentic', 'multi-agent', 'tool use', 'function calling',
  'context window', 'token', 'tokenizer', '128k', '1m tokens',
  'inference', 'latency', 'throughput', 'tps',
  'benchmark', 'mmlu', 'humaneval', 'gsm8k', 'hellaswag',
  'open source', 'open-source', 'open weights',
  'quantization', 'gguf', 'ggml', 'int4', 'int8',
  'moe', 'mixture of experts', 'sparse',

  // IA Générative
  'sora', 'runway', 'pika', 'kling', 'video generation',
  'stable diffusion', 'midjourney', 'dall-e', 'dalle', 'flux',
  'diffusion model', 'text-to-video', 'image generation',

  // Architecture & Recherche
  'attention mechanism', 'self-attention', 'kv cache',
  'pretraining', 'post-training', 'rlhf', 'dpo', 'ppo',
  'scaling law', 'emergent', 'capability', 'reasoning',
  'alignment', 'safety', 'jailbreak', 'red team',
  'arxiv', 'research paper'
];

// === MOTS-CLÉS MEDIUM VALUE (+1 pt) ===
const mediumValueKeywords = [
  'intelligence artificielle', 'artificial intelligence',
  'machine learning', 'ml', 'ai', 'ia',
  'automation', 'automatisation',
  'api', 'sdk', 'framework',
  'hugging face', 'huggingface',
  'langchain', 'llamaindex', 'semantic kernel', 'autogen',
  'gpu', 'cuda', 'tensor', 'pytorch', 'tensorflow'
];

// === SCORER CHAQUE ARTICLE ===
const scoredArticles = articles.map(article => {
  const title = (article.title || '').toLowerCase();
  const description = (article.description || article.contentSnippet || article.content || '').toLowerCase();
  const text = title + ' ' + description;

  let score = 0;
  let matchedKeywords = [];

  // High value = +3 points
  highValueKeywords.forEach(kw => {
    if (text.includes(kw.toLowerCase())) {
      score += 3;
      if (!matchedKeywords.includes(kw)) matchedKeywords.push(kw);
    }
  });

  // Medium value = +1 point
  mediumValueKeywords.forEach(kw => {
    if (text.includes(kw.toLowerCase())) {
      score += 1;
      if (!matchedKeywords.includes(kw)) matchedKeywords.push(kw);
    }
  });

  // Bonus pour benchmarks/comparaisons
  if (text.includes('vs') || text.includes('versus') || text.includes('compared') || text.includes('benchmark')) {
    score += 2;
  }

  // Bonus pour annonces majeures
  if (text.includes('launch') || text.includes('release') || text.includes('announce') || 
      text.includes('introduces') || text.includes('unveils') ||
      text.includes('lancé') || text.includes('sortie') || text.includes('annonce')) {
    score += 3;
  }

  // Bonus pour articles récents
  const pubDate = new Date(article.isoDate || article.pubDate);
  const hoursSincePublished = (Date.now() - pubDate.getTime()) / (1000 * 60 * 60);
  if (hoursSincePublished < 12) score += 5;
  else if (hoursSincePublished < 24) score += 4;
  else if (hoursSincePublished < 48) score += 2;
  else if (hoursSincePublished < 72) score += 1;

  // Détecter la langue
  const isEnglish = !/[àâäéèêëïîôùûüçœæ]/i.test(article.title);

  // Extraire image si disponible
  let imageUrl = null;
  if (article.enclosure?.url) imageUrl = article.enclosure.url;
  else if (article['media:content']?.$.url) imageUrl = article['media:content'].$.url;
  else if (article['media:thumbnail']?.$.url) imageUrl = article['media:thumbnail'].$.url;
  else if (article.image) imageUrl = article.image;

  return {
    ...article,
    relevanceScore: score,
    matchedKeywords: [...new Set(matchedKeywords)].slice(0, 8),
    hoursSincePublished: Math.round(hoursSincePublished),
    isEnglish: isEnglish,
    extractedImageUrl: imageUrl,
    source: article.creator || article.author || article['dc:creator'] || 'Source IA'
  };
});

// === DÉDUPLIQUER ===
const uniqueArticles = new Map();
scoredArticles.forEach(article => {
  const normalizedTitle = article.title
    .toLowerCase()
    .replace(/[^a-z0-9àâäéèêëïîôùûüç]/g, '')
    .substring(0, 50);

  if (!uniqueArticles.has(normalizedTitle) || 
      uniqueArticles.get(normalizedTitle).relevanceScore < article.relevanceScore) {
    uniqueArticles.set(normalizedTitle, article);
  }
});

// === TRIER PAR SCORE ===
const sorted = Array.from(uniqueArticles.values())
  .filter(a => a.relevanceScore >= 6) // Seuil minimum
  .sort((a, b) => b.relevanceScore - a.relevanceScore);

// === MODE ÉDUCATIF SI PAS DE NEWS ===
if (sorted.length === 0) {
  const educationalTopics = [
    {
      title: 'Comment fonctionne un Transformer : le mécanisme d\'attention expliqué',
      angle: 'architecture_transformer'
    },
    {
      title: 'RAG vs Fine-tuning : quand utiliser quoi pour ton LLM ?',
      angle: 'rag_vs_finetuning'
    },
    {
      title: 'GPT-4 vs Claude 3.5 vs Gemini 2 : les vraies différences d\'architecture',
      angle: 'comparaison_llm'
    },
    {
      title: 'Embeddings et Vector Databases : le guide complet pour builders',
      angle: 'embeddings_vectordb'
    },
    {
      title: 'Prompt Engineering avancé : Chain of Thought et ses variantes',
      angle: 'prompt_engineering'
    },
    {
      title: 'Mixture of Experts (MoE) : pourquoi Mixtral et GPT-4 l\'utilisent',
      angle: 'moe_architecture'
    },
    {
      title: 'Quantization : faire tourner Llama 3 70B sur un laptop',
      angle: 'quantization'
    },
    {
      title: 'Agents IA : architectures et patterns pour builders',
      angle: 'agents_ia'
    },
    {
      title: 'RLHF vs DPO : comment aligner un LLM sur les préférences humaines',
      angle: 'alignment_methods'
    },
    {
      title: 'Context Window : pourquoi 128K tokens ne suffit pas toujours',
      angle: 'context_window'
    },
    {
      title: 'Function Calling : comment les LLMs utilisent des outils externes',
      angle: 'function_calling'
    },
    {
      title: 'Les tokenizers expliqués : BPE, SentencePiece et leurs impacts',
      angle: 'tokenizers'
    }
  ];

  const selected = educationalTopics[Math.floor(Math.random() * educationalTopics.length)];

  return [{
    json: {
      mode: 'educational',
      noNewsFound: true,
      educationalTopic: selected.title,
      educationalAngle: selected.angle,
      postType: context.postType,
      postTypeLabel: '📚 Deep Dive Éducatif',
      currentDate: context.currentDate,
      readableDate: context.readableDate,
      hasImage: false,
      imageUrl: null
    }
  }];
}

// === MODE NEWS : RETOURNER LE MEILLEUR ARTICLE ===
const selected = sorted[0];

return [{
  json: {
    mode: 'news',
    noNewsFound: false,
    title: selected.title,
    description: selected.description || selected.contentSnippet || '',
    content: selected.content || selected['content:encoded'] || '',
    link: selected.link,
    pubDate: selected.pubDate || selected.isoDate,
    source: selected.source,
    relevanceScore: selected.relevanceScore,
    matchedKeywords: selected.matchedKeywords,
    isEnglish: selected.isEnglish,
    hasImage: !!selected.extractedImageUrl,
    imageUrl: selected.extractedImageUrl,
    totalArticlesFound: sorted.length,
    postType: context.postType,
    postTypeLabel: context.postTypeLabel,
    currentDate: context.currentDate,
    readableDate: context.readableDate
  }
}];

// =============================================================
// 📝 PREPARE NEWS DATA - Pour le mode actualité
// =============================================================

const data = items[0].json;

return [{
  json: {
    mode: 'news',
    articleTitle: data.title,
    articleDescription: data.description,
    articleContent: data.content?.substring(0, 3000) || data.description,
    articleLink: data.link,
    articleSource: data.source,
    matchedKeywords: data.matchedKeywords || [],
    isEnglish: data.isEnglish,
    hasImage: data.hasImage,
    imageUrl: data.imageUrl,
    postType: data.postType,
    postTypeLabel: data.postTypeLabel,
    currentDate: data.currentDate,
    readableDate: data.readableDate,
    relevanceScore: data.relevanceScore,
    totalArticlesFound: data.totalArticlesFound
  }
}];

// =============================================================
// 📝 PREPARE EDUCATIONAL DATA - Pour le mode éducatif
// =============================================================

const data = items[0].json;

return [{
  json: {
    mode: 'educational',
    articleTitle: data.educationalTopic,
    articleDescription: `Post éducatif technique sur : ${data.educationalTopic}`,
    articleContent: '',
    articleLink: null,
    articleSource: 'Contenu éducatif original',
    educationalAngle: data.educationalAngle,
    matchedKeywords: [],
    isEnglish: false,
    hasImage: false,
    imageUrl: null,
    postType: data.postType,
    postTypeLabel: '📚 Deep Dive Éducatif',
    currentDate: data.currentDate,
    readableDate: data.readableDate
  }
}];

