parameters.jsCode:
// =============================================================
// 📝 PREPARE FINAL POST
// =============================================================

const contentData = $('🤖 AI Content Generator').first().json.output;
const articleData = $('🔗 Merge Modes').first().json;

const postId = `post_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

// Hashtags
const hashtagString = contentData.hashtags
  .map(h => h.startsWith('#') ? h : `#${h}`)
  .join(' ');

const fullPostContent = `${contentData.postContent}\n\n${hashtagString}`;

return [{
  json: {
    postId,
    mode: articleData.mode,

    // Contenu
    postContent: contentData.postContent,
    fullPostContent,
    hookLine: contentData.hookLine,
    strategicAngle: contentData.strategicAngle,

    // Hashtags
    hashtags: contentData.hashtags,
    hashtagString,

    // Image (seulement pour news avec image source)
    hasImage: articleData.hasImage && articleData.mode === 'news',
    imageUrl: articleData.imageUrl || null,

    // Métadonnées
    postType: articleData.postType,
    postTypeLabel: articleData.postTypeLabel,
    currentDate: articleData.currentDate,
    readableDate: articleData.readableDate,

    // Article source
    articleTitle: articleData.articleTitle,
    articleLink: articleData.articleLink || null,
    articleSource: articleData.articleSource,

    // Statut
    status: 'pending_review',
    createdAt: new Date().toISOString()
  }
}];

